    ctx.beginPath();
    ctx.arc(comet.x, comet.y, pulseRingRadius, 0, Math.PI * 2);
    ctx.strokeStyle = PALETTE.accentCyan;
    ctx.lineWidth = 2.0;
    ctx.globalAlpha = 0.45 + 0.45 * breath;
