  ctx.beginPath();
  ctx.arc(well.x, well.y, well.pullRadius, 0, Math.PI * 2);
  ctx.strokeStyle = PALETTE.wellWave;
  ctx.globalAlpha = 0.45 * fadeAlpha;
  ctx.lineWidth = 1.6;
  ctx.setLineDash([6, 8]);
