    portalGrad.addColorStop(0.4, PALETTE.gateInnerPulse);
    portalGrad.addColorStop(0.8, 'rgba(255, 77, 148, 0.32)');
    portalGrad.addColorStop(1, 'rgba(255, 77, 148, 0)');
  } else {
